{
 "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
 "description": "Operator families, every query: untraced median runtime per TPC-H query and build, split by each operator family's share of perf-sampled cycles. Typer builds are not split.",
 "data": {
  "name": "table"
 },
 "params": [
  {
   "name": "machine",
   "value": "burrata",
   "bind": {
    "input": "select",
    "options": [
     "burrata",
     "roquefort",
     "manchego",
     "dubliner"
    ],
    "name": "Machine "
   }
  },
  {
   "name": "mode",
   "value": "ms",
   "bind": {
    "input": "select",
    "options": [
     "ms",
     "pct"
    ],
    "labels": [
     "Runtime ms",
     "% of cycles"
    ],
    "name": "Show "
   }
  }
 ],
 "transform": [
  {
   "filter": "datum.machine === machine && datum.build !== 'VW:par_crc32'"
  },
  {
   "calculate": "mode === 'pct' ? datum.pct : datum.ms",
   "as": "value"
  }
 ],
 "facet": {
  "column": {
   "field": "query",
   "type": "ordinal",
   "sort": {
    "field": "query_order"
   },
   "header": {
    "title": null,
    "labelOrient": "bottom",
    "labelFontWeight": "bold",
    "labelPadding": 4
   }
  }
 },
 "spacing": 6,
 "spec": {
  "width": 134,
  "height": 200,
  "mark": {
   "type": "bar",
   "cornerRadiusEnd": 0,
   "tooltip": true
  },
  "encoding": {
   "x": {
    "field": "build_short",
    "type": "nominal",
    "sort": [
     "T",
     "TW",
     "VW"
    ],
    "title": null,
    "scale": {
     "paddingInner": 0.12,
     "paddingOuter": 0.1
    },
    "axis": {
     "labelAngle": 0,
     "ticks": false,
     "domain": false,
     "labelFontSize": 9,
     "labelPadding": 3,
     "labelAlign": "center",
     "labelBaseline": "top"
    }
   },
   "y": {
    "field": "value",
    "type": "quantitative",
    "stack": "zero",
    "title": null,
    "axis": {
     "labelExpr": "mode === \"pct\" ? datum.label + \"%\" : (datum.index == 1 ? datum.label + \" ms\" : datum.label)"
    }
   },
   "color": {
    "field": "family",
    "type": "nominal",
    "title": null,
    "scale": {
     "domain": [
      "Hashing",
      "Inlined hashing",
      "Join",
      "Selection",
      "Aggregation",
      "Projection",
      "Other",
      "Runtime (compiled, not split)"
     ],
     "range": [
      "#fc8d62",
      "#e5c494",
      "#8da0cb",
      "#66c2a5",
      "#e78ac3",
      "#ffd92f",
      "#a6d854",
      "#b3b3b3"
     ]
    },
    "legend": {
     "orient": "top",
     "columns": 4,
     "symbolType": "square",
     "labelLimit": 170,
     "columnPadding": 10,
     "labelExpr": "datum.label === \"Runtime (compiled, not split)\" ? \"Compiled, not split\" : datum.label"
    }
   },
   "order": {
    "field": "family_order",
    "type": "quantitative",
    "sort": "ascending"
   },
   "opacity": {
    "condition": {
     "test": "mode === 'pct' && datum.solid == 1",
     "value": 0.35
    },
    "value": 1
   },
   "tooltip": [
    {
     "field": "query"
    },
    {
     "field": "build"
    },
    {
     "field": "family"
    },
    {
     "field": "ms",
     "type": "quantitative",
     "format": ".1f",
     "title": "ms"
    },
    {
     "field": "pct",
     "type": "quantitative",
     "format": ".1f",
     "title": "% of cycles"
    },
    {
     "field": "run_ms",
     "type": "quantitative",
     "format": ".1f",
     "title": "run ms"
    }
   ]
  }
 },
 "resolve": {
  "scale": {
   "y": "shared"
  }
 }
}

{
 "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
 "description": "Runtime per TPC-H query and build, split into retiring and the Sirin & Ailamaki stall categories.",
 "data": {
  "name": "table"
 },
 "params": [
  {
   "name": "machine",
   "value": "dubliner",
   "bind": {
    "input": "select",
    "options": [
     "dubliner",
     "manchego"
    ],
    "name": "Machine "
   }
  },
  {
   "name": "mode",
   "value": "pct",
   "bind": {
    "input": "select",
    "options": [
     "pct",
     "stall",
     "ms"
    ],
    "labels": [
     "% of runtime",
     "% of stall time",
     "Runtime ms"
    ],
    "name": "Show "
   }
  }
 ],
 "transform": [
  {
   "filter": "datum.machine == machine && (mode != 'stall' || datum.category != 'Retiring')"
  },
  {
   "calculate": "100 * datum.value_ms / datum.total_ms",
   "as": "pct_of_total"
  },
  {
   "calculate": "mode == 'pct' ? datum.pct_of_total : mode == 'stall' ? datum.pct_of_stall : datum.value_ms",
   "as": "y"
  }
 ],
 "facet": {
  "column": {
   "field": "query_label",
   "type": "ordinal",
   "sort": {
    "field": "query"
   },
   "title": null,
   "header": {
    "labelOrient": "bottom",
    "labelPadding": 4
   }
  }
 },
 "spacing": 8,
 "spec": {
  "width": 134,
  "height": 200,
  "mark": {
   "type": "bar",
   "width": 22
  },
  "encoding": {
   "x": {
    "field": "build_short",
    "type": "nominal",
    "sort": {
     "field": "build_order",
     "op": "min"
    },
    "title": null,
    "axis": {
     "labelAngle": 0,
     "labelFontSize": 9,
     "labelPadding": 3,
     "ticks": false,
     "domain": false
    }
   },
   "y": {
    "field": "y",
    "type": "quantitative",
    "stack": "zero",
    "axis": {
     "title": {
      "expr": "mode == 'pct' ? '% of runtime' : mode == 'stall' ? '% of stall time' : 'Runtime ms'"
     }
    }
   },
   "color": {
    "field": "category",
    "type": "nominal",
    "scale": {
     "domain": [
      "Retiring",
      "Execution",
      "Dcache",
      "Decoding",
      "Branch misp.",
      "Icache",
      "Machine clears"
     ],
     "range": [
      "#fc8d62",
      "#e78ac3",
      "#8da0cb",
      "#66c2a5",
      "#ffd92f",
      "#e5c494",
      "#a6d854"
     ]
    },
    "sort": [
     "Retiring",
     "Execution",
     "Dcache",
     "Decoding",
     "Branch misp.",
     "Icache",
     "Machine clears"
    ],
    "title": null,
    "legend": {
     "orient": "top",
     "direction": "horizontal",
     "columns": 4
    }
   },
   "order": {
    "field": "category_order",
    "type": "quantitative"
   },
   "tooltip": [
    {
     "field": "query_label",
     "title": "Query"
    },
    {
     "field": "build",
     "title": "Build"
    },
    {
     "field": "category",
     "title": "Category"
    },
    {
     "field": "value_ms",
     "title": "ms",
     "format": ".1f"
    },
    {
     "field": "pct_of_total",
     "title": "% of runtime",
     "format": ".1f"
    },
    {
     "field": "pct_of_stall",
     "title": "% of stall",
     "format": ".1f"
    },
    {
     "field": "stall_ms",
     "title": "Stall ms",
     "format": ".1f"
    },
    {
     "field": "total_ms",
     "title": "Runtime ms",
     "format": ".1f"
    }
   ]
  }
 },
 "resolve": {
  "scale": {
   "x": "independent"
  }
 }
}

{
 "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
 "description": "Stalls per operator: for the selected query, each operator's runtime (its share of cycles x untraced runtime) split by top-down category; grouped by build. Categories depend on the machine's PMU model.",
 "data": {
  "name": "table"
 },
 "params": [
  {
   "name": "machine",
   "value": "burrata",
   "bind": {
    "input": "select",
    "options": [
     "burrata",
     "roquefort",
     "manchego",
     "dubliner"
    ],
    "name": "Machine "
   }
  },
  {
   "name": "q",
   "value": "Q1",
   "bind": {
    "input": "select",
    "options": [
     "Q1",
     "Q3",
     "Q6",
     "Q9",
     "Q18"
    ],
    "name": "Query "
   }
  },
  {
   "name": "smode",
   "value": "ms",
   "bind": {
    "input": "select",
    "options": [
     "ms",
     "pct"
    ],
    "labels": [
     "Runtime ms",
     "% of operator"
    ],
    "name": "Show "
   }
  }
 ],
 "transform": [
  {
   "filter": "datum.machine === machine && datum.query === q"
  },
  {
   "calculate": "smode === 'pct' ? 100 * datum.frac : datum.ms",
   "as": "value"
  },
  {
   "calculate": "datum.build + '  (' + format(datum.build_ms, '.1f') + ' ms)'",
   "as": "build_head"
  },
  {
   "calculate": "smode === 'pct' ? format(datum.op_ms, '.1f') + ' ms' : format(100 * datum.op_share, '.0f') + '%'",
   "as": "end_label"
  }
 ],
 "facet": {
  "row": {
   "field": "build_head",
   "type": "nominal",
   "sort": {
    "field": "build_order"
   },
   "header": {
    "title": null,
    "labelAngle": 0,
    "labelAlign": "left",
    "labelOrient": "top",
    "labelAnchor": "start",
    "labelFontWeight": "bold",
    "labelPadding": 1,
    "labelFontSize": 12
   }
  }
 },
 "spacing": 4,
 "resolve": {
  "scale": {
   "y": "independent"
  }
 },
 "spec": {
  "width": 480,
  "height": {
   "step": 20
  },
  "encoding": {
   "y": {
    "field": "op_label",
    "type": "nominal",
    "title": null,
    "sort": {
     "field": "op_order",
     "op": "min"
    },
    "axis": {
     "ticks": false,
     "domain": false,
     "labelLimit": 250,
     "labelFontSize": 12
    }
   }
  },
  "layer": [
   {
    "mark": {
     "type": "bar",
     "height": {
      "band": 0.85
     },
     "tooltip": true
    },
    "encoding": {
     "x": {
      "field": "value",
      "type": "quantitative",
      "stack": "zero",
      "title": null,
      "axis": {
       "tickCount": 6,
       "labelFontSize": 11,
       "labelExpr": "smode === \"pct\" ? datum.label + \"%\" : (datum.index == 1 ? datum.label + \" ms\" : datum.label)"
      }
     },
     "color": {
      "field": "category",
      "type": "nominal",
      "title": null,
      "scale": {
       "domain": [
        "Retiring",
        "Front end",
        "Bad speculation",
        "Other (incl. bad spec.)",
        "Back end: memory",
        "Back end: core",
        "Back end"
       ],
       "range": [
        "#fc8d62",
        "#66c2a5",
        "#ffd92f",
        "#ffd92f",
        "#8da0cb",
        "#e78ac3",
        "#8da0cb"
       ]
      },
      "legend": {
       "orient": "top",
       "columns": 3,
       "symbolType": "square",
       "labelLimit": 220
      }
     },
     "order": {
      "field": "category_order",
      "type": "quantitative",
      "sort": "ascending"
     },
     "tooltip": [
      {
       "field": "build"
      },
      {
       "field": "op_family",
       "title": "family"
      },
      {
       "field": "operator"
      },
      {
       "field": "category"
      },
      {
       "field": "frac",
       "type": "quantitative",
       "format": ".0%",
       "title": "of operator"
      },
      {
       "field": "ms",
       "type": "quantitative",
       "format": ".1f",
       "title": "ms"
      },
      {
       "field": "op_ms",
       "type": "quantitative",
       "format": ".1f",
       "title": "operator ms"
      },
      {
       "field": "op_share",
       "type": "quantitative",
       "format": ".0%",
       "title": "of run"
      }
     ]
    }
   },
   {
    "transform": [
     {
      "aggregate": [
       {
        "op": "sum",
        "field": "value",
        "as": "tot"
       },
       {
        "op": "min",
        "field": "end_label",
        "as": "end_label"
       }
      ],
      "groupby": [
       "op_label",
       "op_order"
      ]
     }
    ],
    "mark": {
     "type": "text",
     "align": "left",
     "dx": 5,
     "fontSize": 12
    },
    "encoding": {
     "x": {
      "field": "tot",
      "type": "quantitative"
     },
     "text": {
      "field": "end_label"
     }
    }
   }
  ]
 }
}
